macro_rules! deps {
    () => {
        DFA!();
        MatchErrorKind!();
    };
}

macro_rules! MatchError {
    () => {
        deps!();
        # [doc = " An error indicating that a search stopped before reporting whether a"] # [doc = " match exists or not."] # [doc = ""] # [doc = " To be very clear, this error type implies that one cannot assume that no"] # [doc = " matches occur, since the search stopped before completing. That is, if"] # [doc = " you're looking for information about where a search determined that no"] # [doc = " match can occur, then this error type does *not* give you that. (Indeed, at"] # [doc = " the time of writing, if you need such a thing, you have to write your own"] # [doc = " search routine.)"] # [doc = ""] # [doc = " Normally, when one searches for something, the response is either an"] # [doc = " affirmative \"it was found at this location\" or a negative \"not found at"] # [doc = " all.\" However, in some cases, a regex engine can be configured to stop its"] # [doc = " search before concluding whether a match exists or not. When this happens,"] # [doc = " it may be important for the caller to know why the regex engine gave up and"] # [doc = " where in the input it gave up at. This error type exposes the 'why' and the"] # [doc = " 'where.'"] # [doc = ""] # [doc = " For example, the DFAs provided by this library generally cannot correctly"] # [doc = " implement Unicode word boundaries. Instead, they provide an option to"] # [doc = " eagerly support them on ASCII text (since Unicode word boundaries are"] # [doc = " equivalent to ASCII word boundaries when searching ASCII text), but will"] # [doc = " \"give up\" if a non-ASCII byte is seen. In such cases, one is usually"] # [doc = " required to either report the failure to the caller (unergonomic) or"] # [doc = " otherwise fall back to some other regex engine (ergonomic, but potentially"] # [doc = " costly)."] # [doc = ""] # [doc = " More generally, some regex engines offer the ability for callers to specify"] # [doc = " certain bytes that will trigger the regex engine to automatically quit if"] # [doc = " they are seen."] # [doc = ""] # [doc = " Still yet, there may be other reasons for a failed match. For example,"] # [doc = " the hybrid DFA provided by this crate can be configured to give up if it"] # [doc = " believes that it is not efficient. This in turn permits callers to choose a"] # [doc = " different regex engine."] # [doc = ""] # [doc = " (Note that DFAs are configured by default to never quit or give up in this"] # [doc = " fashion. For example, by default, a DFA will fail to build if the regex"] # [doc = " pattern contains a Unicode word boundary. One needs to opt into the \"quit\""] # [doc = " behavior via options, like"] # [doc = " [`hybrid::dfa::Config::unicode_word_boundary`](crate::hybrid::dfa::Config::unicode_word_boundary).)"] # [doc = ""] # [doc = " There are a couple other ways a search"] # [doc = " can fail. For example, when using the"] # [doc = " [`BoundedBacktracker`](crate::nfa::thompson::backtrack::BoundedBacktracker)"] # [doc = " with a haystack that is too long, or trying to run an unanchored search"] # [doc = " with a [one-pass DFA](crate::dfa::onepass)."] # [derive (Clone , Debug , Eq , PartialEq)] pub struct MatchError (# [cfg (feature = "alloc")] alloc :: boxed :: Box < MatchErrorKind > , # [cfg (not (feature = "alloc"))] MatchErrorKind ,) ;
    };
}

MatchError!()